Try this. Paste the below into a text editor, save as a *.js file, include as a plugin.
Code:
Window_Message.prototype.calcTextHeight = function(textState, all) {
var lastFontSize = this.contents.fontSize;
var textHeight = 0;
var lines = textState.text.slice(textState.index).split('\n');
var maxLines = all ? lines.length : 1;

for (var i = 0; i < maxLines; i++) {
    var maxFontSize = this.contents.fontSize;
    var regExp = /\x1b[\{\}]/g;
    for (;;) {
        var array = regExp.exec(lines[i]);
            if (array) {
                if (array[0] === '\x1b{')
                    this.makeFontBigger();
                if (array[0] === '\x1b}')
                    this.makeFontSmaller();
                if (maxFontSize < this.contents.fontSize)
                    maxFontSize = this.contents.fontSize;
            }
            else
                break;
    }
// Change the ID on the next line
    textHeight += maxFontSize + $gameVariables.value(2);
}
this.contents.fontSize = lastFontSize;
return textHeight;
};
Change the variable ID on the specified line from 42 to whatever you want. The value of that variable will now be the extra space added between lines of text. Remember that the default is 8.
So you can at any time do Control Variables and change the value of that variable.

Okay, one thing I found difficult to handle is how the line height change was not making message windows smaller to size. So I decided to try to fix that. And I ended up with code that seems way too complex.
Code:
/*:
 * @plugindesc Custom Message Window Height Plugin
 * @param customFontSize
 * @desc Set the custom font size for the message window.
 * @default 28
 * @help This plugin adjusts the message window height based on a custom font size if no face graphic is requested.
 */

(function() {
    var parameters = PluginManager.parameters('CustomMessageWindowHeight');
    var customFontSize = Number(parameters['customFontSize'] || 28);
    var _Window_Message_fittingHeight = Window_Message.prototype.fittingHeight;

    // Hook into the message setup phase to detect face graphic presence
    var _Game_Message_setFaceImage = Game_Message.prototype.setFaceImage;
    Game_Message.prototype.setFaceImage = function(faceName, faceIndex) {
        this._isFaceGraphicPresent = faceName && faceName !== '';
        _Game_Message_setFaceImage.call(this, faceName, faceIndex);
    };

    // Ensure isFaceGraphicPresent is checked at the start of each message
    var _Window_Message_startMessage = Window_Message.prototype.startMessage;
    Window_Message.prototype.startMessage = function() {
        $gameMessage._isFaceGraphicPresent = $gameMessage.faceName() && $gameMessage.faceName() !== '';
        _Window_Message_startMessage.call(this);
    };

    // fittingHeight toggle between custom font size and core logic
    Window_Message.prototype.fittingHeight = function(numLines) {
        if ($gameMessage._isFaceGraphicPresent) {
            // Use the default fittingHeight if a face graphic is requested
            return _Window_Message_fittingHeight.call(this, numLines);
        } else {
            // Use the custom fittingHeight if no face graphic is requested
            return numLines * customFontSize + $gameVariables.value(100);
        }
    };

    Window_Message.prototype.resetFontSettings = function() {
        this.contents.fontSize = customFontSize;
    };

    // override for ensuring proper handling of face graphics
    var _Window_Message_newPage = Window_Message.prototype.newPage;
    Window_Message.prototype.newPage = function(textState) {
        this.contents.clear();
        this.resetFontSettings();
        this.clearFlags();
        this.loadMessageFace();
        textState.x = this.newLineX();
        textState.y = 0;
        textState.left = this.newLineX();
        textState.height = this.calcTextHeight(textState, false);
        _Window_Message_newPage.call(this, textState);
    };

    // handle face graphic presence and loading
    var _Window_Message_updateLoading = Window_Message.prototype.updateLoading;
    Window_Message.prototype.updateLoading = function() {
        if (this._faceBitmap) {
            if (this._faceBitmap.isReady()) {
                this.drawMessageFace();
                this._faceBitmap = null;
                return false;
            } else {
                return true;
            }
        } else {
            return _Window_Message_updateLoading.call(this);
        }
    };
})();
